import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for any subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("throws for invalid percent values", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("computes correct discount rounded down", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(10000)).toBe(1000);
    expect(policy.computeDiscountCents(1001)).toBe(100); // floor(1001*10/100)=100
  });

  it("returns 0 for zero or negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });

  it("handles 0% and 100%", () => {
    expect(new PercentageDiscountPolicy(0).computeDiscountCents(5000)).toBe(0);
    expect(new PercentageDiscountPolicy(100).computeDiscountCents(5000)).toBe(5000);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("throws for invalid amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    expect(() => new FixedAmountDiscountPolicy(1.5)).toThrow(RangeError);
  });

  it("returns the fixed amount when subtotal is larger", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(1000)).toBe(500);
  });

  it("caps discount at subtotal when subtotal is smaller", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(300)).toBe(300);
  });

  it("returns 0 for zero or negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
    expect(policy.computeDiscountCents(-10)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("throws when given an empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow();
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, plus 200 = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 10000 = 1000, remaining = 9000
      // Second: 10% of 9000 = 900, remaining = 8100
      // Total discount = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("stops reducing once remaining is zero", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // subtotal=800: first takes min(1000,800)=800, remaining=0, second takes 0
      expect(composite.computeDiscountCents(800)).toBe(800);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(5000)).toBe(300);
  });
});

