import type { Product, CartLine } from "../src/product.ts";

const product = (id: string, price = 1000, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart - line management", () => {
  it("starts empty", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("adds products and tracks quantity", () => {
    const cart = new Cart();
    cart.add(product("a"), 2);
    cart.add(product("b"), 1);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities for same product", () => {
    const cart = new Cart();
    cart.add(product("a"), 2);
    cart.add(product("a"), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("throws for non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a"), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a"), -1)).toThrow(RangeError);
    expect(() => cart.add(product("a"), 1.5)).toThrow(RangeError);
  });

  it("throws for negative unit price", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a product", () => {
    const cart = new Cart();
    cart.add(product("a"), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing non-existent product", () => {
    const cart = new Cart();
    expect(cart.remove("nope")).toBe(false);
  });

  it("updates quantity", () => {
    const cart = new Cart();
    cart.add(product("a"), 5);
    cart.updateQuantity("a", 3);
    expect(cart.itemCount).toBe(3);
  });

  it("removes product when updateQuantity is 0", () => {
    const cart = new Cart();
    cart.add(product("a"), 5);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("throws on updateQuantity for non-existent product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 1)).toThrow();
  });

  it("throws on updateQuantity with invalid value", () => {
    const cart = new Cart();
    cart.add(product("a"), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clears all lines", () => {
    const cart = new Cart();
    cart.add(product("a"), 2);
    cart.add(product("b"), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });
});

describe("Cart - totals with mocked collaborators", () => {
  it("computes subtotal from lines", () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    cart.add(product("b", 300), 1);
    expect(cart.totals().subtotalCents).toBe(1300);
  });

  it("applies discount policy (clamped)", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(200);
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("clamps discount to subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product("a", 500), 1);
    expect(cart.totals().discountCents).toBe(500);
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product("a", 500), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("applies tax on discounted subtotal", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy, taxCalculator });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US");
  });

  it("applies shipping on discounted subtotal", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(product("a", 2000), 1);
    const totals = cart.totals();
    expect(totals.shippingCents).toBe(500);
  });

  it("clamps negative tax and shipping to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-10),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-5),
    };
    const cart = new Cart({ taxCalculator, shippingCalculator });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
  });

  it("computes totalCents = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=100, discounted=900, tax=72, shipping=500
    expect(totals.totalCents).toBe(900 + 72 + 500);
  });

  it("uses custom region for tax", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

