describe("Cart - checkout", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("throws InventoryError when item is not available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
  });

  it("throws InventoryError when availableQuantity < requested", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
  });

  it("passes when available and quantity sufficient", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("passes when available with no availableQuantity field", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ region: "US-TX" });
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout({ asyncTaxProvider });
    // tax = floor(1000 * 0.1) = 100
    expect(result.totals.taxCents).toBe(100);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-TX");
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(600),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };
    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // subtotal = 600*2 = 1200, tax = floor(1200*0.05)=60
    expect(result.totals.subtotalCents).toBe(1200);
    expect(result.totals.taxCents).toBe(60);
  });

  it("generates default reason when inventory denied without reason", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      expect((e as InventoryError).message).toContain("insufficient stock");
      expect((e as InventoryError).available).toBe(2);
    }
  });
});

