toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (id: string, weightGrams?: number, quantity = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("always returns 0", () => {
    expect(calc.computeShippingCents([makeLine("a")], 10000)).toBe(0);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("throws for invalid flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    expect(() => new FlatShippingCalculator(1.5)).toThrow(RangeError);
  });

  it("throws for invalid freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    expect(() => new FlatShippingCalculator(500, 1.5)).toThrow(RangeError);
  });

  it("returns flat cost when below threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a")], 4999)).toBe(500);
  });

  it("returns 0 when subtotal meets freeOver threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a")], 5000)).toBe(0);
    expect(calc.computeShippingCents([makeLine("a")], 6000)).toBe(0);
  });

  it("returns flat cost when no threshold is set", () => {
    const calc = new FlatShippingCalculator(799);
    expect(calc.computeShippingCents([makeLine("a")], 100000)).toBe(799);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("throws for empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow();
  });

  it("throws for invalid bracket upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("throws for invalid bracket costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("throws for invalid overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 50 }], -1),
    ).toThrow(RangeError);
  });

  it("selects the correct bracket based on total weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 2000, costCents: 1000 },
    ]);
    // 200g item -> bracket 500
    expect(calc.computeShippingCents([makeLine("a", 200)], 5000)).toBe(300);
    // 700g -> bracket 1000
    expect(calc.computeShippingCents([makeLine("a", 700)], 5000)).toBe(600);
    // 1500g -> bracket 2000
    expect(calc.computeShippingCents([makeLine("a", 1500)], 5000)).toBe(1000);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [{ upToGrams: 500, costCents: 300 }],
      900,
    );
    expect(calc.computeShippingCents([makeLine("a", 1000)], 5000)).toBe(900);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000)], 5000)).toBe(600);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 when total weight is 0", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 0)], 5000)).toBe(0);
    expect(calc.computeShippingCents([makeLine("a", undefined)], 5000)).toBe(0);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 1000 },
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 400)], 5000)).toBe(300);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 2 items * 300g = 600g -> bracket 1000
    expect(calc.computeShippingCents([makeLine("a", 300, 2)], 5000)).toBe(600);
  });
});

